// ── Helpers ──────────────────────────────────────────────────────────

async function g(path) {
  try {
    const r = await fetch(`${BASE}/${path}`, { signal: AbortSignal.timeout(15000) });
    if (r.status === 204 || r.status >= 400) return null;
    const text = await r.text();
    if (text.trimStart().startsWith('<')) return null;
    const j = JSON.parse(text);
    return j?.data ?? j;
  } catch { return null; }
}

function extractPair(arr) {
  if (!Array.isArray(arr) || !arr.length) return null;
  const kf  = arr.find(c => c.codigoAgrupacionPolitica === 8)
            ?? arr.find(c => (c.nombreCandidato||'').toUpperCase().includes('FUJIMORI'));
  const rsp = arr.find(c => c.codigoAgrupacionPolitica === 10)
            ?? arr.find(c => (c.nombreCandidato||'').toUpperCase().includes('SANCHEZ')
                          && (c.nombreCandidato||'').toUpperCase().includes('ROBERTO'));
  if (!kf && !rsp) return null;
  const kfV  = kf?.totalVotosValidos  ?? 0;
  const rspV = rsp?.totalVotosValidos ?? 0;
  return { keiko_votos: kfV, sanchez_votos: rspV };
}

// Throttled parallel executor — runs at most `limit` tasks concurrently
async function pAll(items, fn, limit) {
  const results = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      const i = next++;
      results[i] = await fn(items[i], i);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

// ── Fetchers ──────────────────────────────────────────────────────────

async function fetchNacional() {
  // tipoFiltro=ambito_geografico es el correcto para R2 2026 (confirmado via XHR intercept 7J)
  const data = await g(
    `resumen-general/participantes?idEleccion=${ID_ELECCION}&tipoFiltro=ambito_geografico&idAmbitoGeografico=${AMBITO_NAC}`
  );
  if (!Array.isArray(data)) return null;
  const pair = extractPair(data);
  if (!pair) return null;
  const kf  = data.find(c => c.codigoAgrupacionPolitica === 8);
  const rsp = data.find(c => c.codigoAgrupacionPolitica === 10);
  return {
    ...pair,
    keiko_pct:   parseFloat((kf?.porcentajeVotosValidos  ?? kf?.porcentajeVotosEmitidos  ?? 0).toFixed(3)),
    sanchez_pct: parseFloat((rsp?.porcentajeVotosValidos ?? rsp?.porcentajeVotosEmitidos ?? 0).toFixed(3)),
  };
}

async function fetchTotales() {
  // tipoFiltro=eleccion da el total nacional de actas (confirmado via XHR intercept 7J)
  const data = await g(
    `resumen-general/totales?idEleccion=${ID_ELECCION}&tipoFiltro=eleccion`
  );
  if (!data) return null;
  return {
    processed: data.actasProcesadas ?? data.actas_procesadas ?? data.contabilizadas ?? null,
    total:     data.actasTotal      ?? data.actas_total      ?? data.totalActas      ?? null,
    pct:       data.porcentajeActas ?? data.pct_actas        ?? data.porcentaje      ?? data.actasContabilizadas ?? null,
    raw:       data,
  };
}

async function fetchDepartamentos() {
  const ubigeos = await g(
    `ubigeos/departamentos?idEleccion=${ID_ELECCION}&idAmbitoGeografico=${AMBITO_NAC}`
  );
  if (!Array.isArray(ubigeos) || !ubigeos.length) return [];
  const results = await Promise.all(ubigeos.map(async dept => {
    const [data, tot] = await Promise.all([
      g(`resumen-general/participantes?idEleccion=${ID_ELECCION}` +
        `&idAmbitoGeografico=${AMBITO_NAC}&tipoFiltro=ubigeo_nivel_01` +
        `&idUbigeoDepartamento=${dept.ubigeo}`),
      g(`resumen-general/totales?idEleccion=${ID_ELECCION}` +
        `&idAmbitoGeografico=${AMBITO_NAC}&tipoFiltro=ubigeo_nivel_01` +
        `&idUbigeoDepartamento=${dept.ubigeo}`),
    ]);
    const pair = extractPair(data);
    if (!pair) return null;
    const pct_actas       = tot?.porcentajeActas ?? tot?.pct_actas ?? tot?.porcentaje ?? null;
    const actas_procesadas = tot?.actasProcesadas ?? tot?.actasContabilizadas ?? null;
    const actas_total      = tot?.actasTotal ?? tot?.totalActas ?? null;
    return { nombre: dept.nombre, ubigeo: dept.ubigeo, ...pair, pct_actas, actas_procesadas, actas_total };
  }));
  return results.filter(Boolean);
}

async function fetchProvincias() {
  const results = await pAll(PROV_CATALOG, async ([deptUbigeo, provUbigeo]) => {
    const data = await g(
      `resumen-general/participantes?idEleccion=${ID_ELECCION}` +
      `&idAmbitoGeografico=${AMBITO_NAC}&tipoFiltro=ubigeo_nivel_02` +
      `&idUbigeoDepartamento=${deptUbigeo}&idUbigeoProvincia=${provUbigeo}`
    );
    const pair = extractPair(data);
    if (!pair) return null;
    if ((pair.keiko_votos + pair.sanchez_votos) === 0) return null;
    return { ubigeo: provUbigeo, deptUbigeo, ...pair };
  }, 20);
  return results.filter(Boolean);
}

async function fetchDistritos() {
  const results = await pAll(DIST_CATALOG, async distUbigeo => {
    const deptUbigeo = distUbigeo.slice(0, 2) + '0000';
    const provUbigeo = distUbigeo.slice(0, 4) + '00';
    const data = await g(
      `resumen-general/participantes?idEleccion=${ID_ELECCION}` +
      `&idAmbitoGeografico=${AMBITO_NAC}&tipoFiltro=ubigeo_nivel_03` +
      `&idUbigeoDepartamento=${deptUbigeo}&idUbigeoProvincia=${provUbigeo}&idUbigeoDistrito=${distUbigeo}`
    );
    const pair = extractPair(data);
    if (!pair) return null;
    if ((pair.keiko_votos + pair.sanchez_votos) === 0) return null;
    return { ubigeo: distUbigeo, ...pair };
  }, 25);
  return results.filter(Boolean);
}

async function fetchExtranjero() {
  const continentes = await g(
    `ubigeos/departamentos?idEleccion=${ID_ELECCION}&idAmbitoGeografico=${AMBITO_EXT}`
  );
  if (!Array.isArray(continentes) || !continentes.length) return [];
  const results = await Promise.all(continentes.map(async cont => {
    const data = await g(
      `resumen-general/participantes?idEleccion=${ID_ELECCION}` +
      `&idAmbitoGeografico=${AMBITO_EXT}&tipoFiltro=ubigeo_nivel_01` +
      `&idUbigeoDepartamento=${cont.ubigeo}`
    );
    const pair = extractPair(data);
    if (!pair) return null;
    return { nombre: cont.nombre, ubigeo: cont.ubigeo, ...pair };
  }));
  return results.filter(Boolean);
}

