async function fetchPaises() {
  const results = await pAll(PAIS_CATALOG, async ([contUbigeo, paisUbigeo]) => {
    const data = await g(
      `resumen-general/participantes?idEleccion=${ID_ELECCION}` +
      `&idAmbitoGeografico=${AMBITO_EXT}&tipoFiltro=ubigeo_nivel_02` +
      `&idUbigeoDepartamento=${contUbigeo}&idUbigeoProvincia=${paisUbigeo}`
    );
    const pair = extractPair(data);
    if (!pair) return null;
    if ((pair.keiko_votos + pair.sanchez_votos) === 0) return null;
    return { ubigeo: paisUbigeo, contUbigeo, ...pair };
  }, 20);
  return results.filter(Boolean);
}

async function buildSnapshot() {
  // All fetchers run in parallel; fetchDistritos throttles internally to 25 concurrent
  const [nacional, totales, departamentos, provincias, distritos, extranjero, paises] = await Promise.all([
    fetchNacional(),
    fetchTotales(),
    fetchDepartamentos(),
    fetchProvincias(),
    fetchDistritos(),
    fetchExtranjero(),
    fetchPaises(),
  ]);

  // Si el endpoint nacional falla, derivar totales de la suma de departamentos
  let keiko_votos   = nacional?.keiko_votos  ?? null;
  let sanchez_votos = nacional?.sanchez_votos ?? null;
  let keiko_pct     = nacional?.keiko_pct    ?? null;
  let sanchez_pct   = nacional?.sanchez_pct  ?? null;

  if (keiko_votos === null && departamentos.length > 0) {
    keiko_votos   = departamentos.reduce((s, d) => s + (d.keiko_votos  || 0), 0);
    sanchez_votos = departamentos.reduce((s, d) => s + (d.sanchez_votos || 0), 0);
    const tot = keiko_votos + sanchez_votos;
    if (tot > 0) {
      keiko_pct   = parseFloat((keiko_votos  / tot * 100).toFixed(3));
      sanchez_pct = parseFloat((sanchez_votos / tot * 100).toFixed(3));
    }
  }

  // pct_actas: sumar actas de depts si el endpoint de totales nacional no responde
  let pct_actas      = totales?.pct       ?? null;
  let actas_total    = totales?.total     ?? null;
  let actas_processed = totales?.processed ?? null;
  if (pct_actas === null && departamentos.length > 0) {
    const sumTotal     = departamentos.reduce((s, d) => s + (d.actas_total      || 0), 0);
    const sumProcessed = departamentos.reduce((s, d) => s + (d.actas_procesadas || 0), 0);
    if (sumTotal > 0) {
      actas_total     = sumTotal;
      actas_processed = sumProcessed;
      pct_actas       = parseFloat((sumProcessed / sumTotal * 100).toFixed(2));
    }
  }

  const hasData = (keiko_votos ?? 0) > 0 || (sanchez_votos ?? 0) > 0;

  return {
    captured_at:        new Date().toISOString(),
    has_data:           hasData,
    actas_total:        actas_total,
    actas_processed:    actas_processed,
    pct_actas:          pct_actas,
    keiko_votos,
    keiko_pct,
    sanchez_votos,
    sanchez_pct,
    dept_breakdown:     departamentos,
    province_breakdown: provincias,
    district_breakdown: distritos,
    ext_breakdown:      extranjero,
    pais_breakdown:     paises,
    totales_raw:        totales?.raw ?? null,
  };
}

async function poll() {
  const t0 = Date.now();
  console.log(`🗳️  ONPE fetch start ${new Date().toLocaleTimeString('es-PE')}`);
  try {
    const snap = await buildSnapshot();
    const elapsed = ((Date.now() - t0) / 1000).toFixed(1);
    if (!snap.has_data) {
      console.log(`⏳ Sin datos aún (${elapsed}s)`);
      return;
    }
    console.log(
      `📊 K=${snap.keiko_pct}% S=${snap.sanchez_pct}%` +
      ` actas=${snap.pct_actas ?? '?'}%` +
      ` depts=${snap.dept_breakdown.length}` +
      ` provs=${snap.province_breakdown.length}` +
      ` dists=${snap.district_breakdown.length}` +
      ` ext=${snap.ext_breakdown.length}` +
      ` paises=${snap.pais_breakdown.length}` +
      ` (${elapsed}s) → enviando a Railway...`
    );

    const resp = await fetch(`${RAILWAY_URL}/api/admin/inject-snapshot`, {
      method:  'POST',
      headers: {
        'Content-Type':  'application/json',
        'Authorization': `Bearer ${ADMIN_SECRET}`,
      },
      body: JSON.stringify(snap),
      signal: AbortSignal.timeout(15000),
    });

    if (!resp.ok) {
      const text = await resp.text().catch(() => '');
      console.error(`❌ Railway error ${resp.status}:`, text.slice(0, 200));
    } else {
      const json = await resp.json().catch(() => ({}));
      console.log(`✅ Guardado. snapshot_id=${json.snapshot_id} granularity=${json.shift_granularity ?? '?'}`);
    }
  } catch (err) {
    console.error('❌ Poll error:', err.message);
  }
}

// ── Start ────────────────────────────────────────────────────────────
let _onpeTimer = null;

function startONPE() {
  if (_onpeTimer) { console.log('Ya corriendo. Usa stopONPE() para detener.'); return; }
  console.log(`🗳️  ONPE bookmarklet started. Polling every ${POLL_INTERVAL/60000} min.`);
  console.log(`   Railway: ${RAILWAY_URL}`);
  console.log(`   Niveles: nacional + 25 depts + 196 provs + 1886 dists + ext (5 cont + 77 países)`);
  poll();
  _onpeTimer = setInterval(poll, POLL_INTERVAL);
}

function stopONPE() {
  if (_onpeTimer) { clearInterval(_onpeTimer); _onpeTimer = null; }
  console.log('🛑 ONPE bookmarklet stopped.');
}

startONPE();

